package com.gameaggregator.auditservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.auditservice.application.AuditService;import com.gameaggregator.auditservice.domain.AuditLog;import com.gameaggregator.auditservice.infrastructure.AuditLogRepository;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/audit-logs") public class AuditController{final AuditService service;final AuditLogRepository repo;public AuditController(AuditService s,AuditLogRepository r){service=s;repo=r;}@PostMapping("/internal")ApiResponse<AuditLog> append(@Valid @RequestBody AuditDtos.Event e){return ApiResponse.success(service.append(e));}@GetMapping ApiResponse<Page<AuditLog>> query(@RequestParam(required=false)UUID tenantId,@RequestParam(required=false)String resourceType,@RequestParam(required=false)String resourceId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var p=PageRequest.of(page,Math.min(size,200));Page<AuditLog> result=tenantId!=null?repo.findAllByTenantIdOrderByOccurredAtDesc(tenantId,p):resourceType!=null&&resourceId!=null?repo.findAllByResourceTypeAndResourceIdOrderByOccurredAtDesc(resourceType,resourceId,p):repo.findAll(p);return ApiResponse.success(result);}}